import { randomBytes } from "node:crypto";
import { homedir } from "node:os";
import { join } from "node:path";
import { chromium } from "playwright";

const OUT = join(homedir(), "development", ".tmp", "stallion-demo-movie", "raw");
const BOARD = `demo-${randomBytes(6).toString("hex")}`;
const URL_ = `http://100.104.44.51:5173/b/${BOARD}`;
const CX = 640;
const CY = 440;
const STEP_MS = 15;

const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({
  viewport: { width: 1280, height: 800 },
  deviceScaleFactor: 1,
  hasTouch: true,
  recordVideo: { dir: OUT, size: { width: 1280, height: 800 } },
});
const page = await context.newPage();
const errors = [];
page.on("pageerror", (e) => errors.push(e.message));
const started = Date.now();

const wait = (ms) => page.waitForTimeout(ms);
const pause = () => wait(400 + Math.random() * 400);
let cdp;
const attach = async () => {
  cdp = await context.newCDPSession(page);
};
const touch = (type, points) =>
  cdp.send("Input.dispatchTouchEvent", {
    type,
    touchPoints: points.map((p, i) => ({ x: p.x, y: p.y, id: i + 1, radiusX: 2, radiusY: 2 })),
  });

const jitter = (v, a = 1.2) => v + (Math.random() - 0.5) * a;

const stroke = async (points) => {
  const [first, ...rest] = points;
